function divMod(a, d) {
  if (typeof a !== "bigint" || typeof d !== "bigint")
    throw new TypeError("Use BigInt integers, such as -17n and 5n");
  if (d <= 0n) throw new RangeError("The divisor must be positive");
  let q = a / d;
  let r = a % d;
  if (r < 0n) { q -= 1n; r += d; }
  return { q, r };
}
